import numpy as np, rcb_panda as rp
s=rp.Session();A=np.load('/app/output/trajectory.npz')['actions'];m=s.model;d=s.data
for end in [675,705,720,800,1055]:
 s.reset()
 for a in A[:end]:s.step(a)
 print('\n',end,'obj',d.xpos[m.body('box').id], 'q',d.xquat[m.body('box').id], 'site',d.site_xpos[m.site('gripper').id],'finger',d.qpos[7:9])
 for i in range(d.ncon):
  c=d.contact[i]
  if 'finger' in m.geom(c.geom1).name or 'finger' in m.geom(c.geom2).name:
   print(m.geom(c.geom1).name,m.geom(c.geom2).name,np.round(c.pos,4),c.dist)
